import React, { useState, useRef, useEffect } from 'react'
import ChatMessage from '../components/ChatMessage/ChatMessage'
import ChatInput from '../components/ChatInput/ChatInput'
import { useQuery } from '../hooks/useSupplyChain'
import './Home.css'

export default function Home() {
  const { loading, runQuery } = useQuery()
  const [messages, setMessages] = useState([])
  const bottomRef = useRef(null)

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages, loading])

  const handleSubmit = async (query, filters) => {
    // Add user message immediately
    setMessages(prev => [...prev, { role: 'user', content: query }])

    const cleanFilters = filters
      ? Object.fromEntries(Object.entries(filters).filter(([, v]) => v))
      : null

    const result = await runQuery(query, cleanFilters || null, 5)

    if (result) {
      setMessages(prev => [...prev, { role: 'assistant', content: result }])
    } else {
      setMessages(prev => [...prev, {
        role: 'error',
        content: 'Something went wrong. Please check that the backend is running and try again.'
      }])
    }
  }

  return (
    <div className="chat-page">
      {/* Message thread */}
      <div className="chat-thread">
        {messages.length === 0 && (
          <div className="chat-empty">
            <div className="chat-empty__icon">⚡</div>
            <h2>Supply Chain Risk Intelligence</h2>
            <p>Ask about supplier delays, shipment disruptions, inventory shortages, or any supply chain risk. Select a sample query below to get started.</p>
          </div>
        )}

        {messages.map((msg, i) => (
          <ChatMessage key={i} message={msg} />
        ))}

        {loading && (
          <div className="chat-msg chat-msg--ai">
            <div className="ai-avatar">AI</div>
            <div className="chat-bubble chat-bubble--ai thinking">
              <span className="dot" /><span className="dot" /><span className="dot" />
            </div>
          </div>
        )}

        <div ref={bottomRef} />
      </div>

      {/* Sticky input at bottom */}
      <ChatInput onSubmit={handleSubmit} loading={loading} />
    </div>
  )
}
